window.AUTH=window.AUTH||{};window.AUTH["10-875"]={"d":"10-875","id":"2011/10-875","n":"Hall v. United States","src":["osg"],"briefs":[{"k":"respondent","label":"Brief for the United States","date":"","url":"https://www.justice.gov/osg/media/196801/dl?inline","side":"res","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/hall-v-united-states-brief-merits","n":110}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep566/usrep566506/usrep566506.pdf","tr":true,"items":[{"t":"case","label":"Connecticut Nat’l Bank v. Germain","cite":"503 U.S. 249","y":1992,"id":"1991/90-1791","sc":1,"sum":"An interlocutory order issued by a district court sitting as a court of appeals in bankruptcy is appealable under the unambiguous language of 28 U. S. C. § 1292. That section provides for review in the courts of appeals, in certain circumstances, of \"[i]nterlocutory orders of the district courts,\" and does not limit such review to orders issued by district courts sitting as bankruptcy trial courts rather than …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31, 32"}},{"t":"case","label":"Dewsnup v. Timm","cite":"502 U.S. 410","y":1992,"id":"1991/90-741","sc":1,"op":1,"sum":"Section 506(d) does not allow Dewsnup to \"strip down\" respondents' lien to the judicially determined value of the collateral, because respondents' claim is secured by a lien and has been fully allowed pursuant to § 502 and, therefore, cannot be classified as \"not an allowed secured claim\" for purposes of the lien-voiding provision of § 506(d).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"14"}},{"t":"case","label":"Doe v. Chao","cite":"540 U.S. 614","y":2004,"id":"2003/02-1377","sc":1,"sum":"The Court reasoned that \"a straightforward textual analysis\" of the Privacy Act shows that the statute guarantees the $1000 minimum for victims of willful Privacy Act violations only in relation to \"actual damages sustained.\" Individuals subjected to an adverse effect - like the miners in this case - have \"injury enough to open the courthouse door, but without more\" have \"no cause of action for damages under the Privacy Act.\".","sumSrc":"Oyez","by":{"0":"32"}},{"t":"case","label":"Helvering v. Stockholms Enskilda Bank","cite":"293 U.S. 84","y":1934,"id":"scdb/1934-037","sc":1,"sum":"Assistant Solicitor General MacLean, with whom Solicitor General Biggs, Assistant Attorney General Wideman, and Messrs. James W. Morris, John H. McEvers, and W. Marvin Smith were on the brief, for petitioner.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"14"}},{"t":"case","label":"Holywell Corp. v. Smith","cite":"503 U.S. 47","y":1992,"id":"1991/90-1361","sc":1,"op":1,"ar":1,"sum":"Smith is required by the Code to file income tax returns and pay taxes on the income attributable to the property of both the corporate debtors and Gould.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"13, 23, 26"}},{"t":"case","label":"Knudsen v. IRS","cite":"581 F.3d 696","y":2009,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/581/696/","op":1,"ar":3,"by":{"0":"6"}},{"t":"case","label":"Massachusetts v. EPA","cite":"549 U.S. 497","y":2007,"id":"2006/05-1120","sc":1,"sum":"The Court ruled that states could sue the EPA for potential damage to their territory caused by global warming, and that the Clean Air Act imposes a duty upon the EPA to regulate the emissions of carbon dioxide and other gases that contribute to global warming.","sumSrc":"Oyez","by":{"0":"32"}},{"t":"case","label":"Nicholas v. United States","cite":"384 U.S. 678","y":1986,"id":"1965/650","sc":1,"op":1,"ar":3,"sum":"A corporation filed a petition for an arrangement with unsecured creditors under Chapter XI of the Bankruptcy Act. While operating its business as a debtor in possession the corporation withheld federal income and social security taxes and collected cabaret excise taxes. It then filed a petition in bankruptcy and was adjudged a bankrupt. Petitioner, who was appointed truste6 in bankruptcy, did not pay the taxes when …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"30"}},{"t":"case","label":"Pelofsky v. Wallace","cite":"102 F.3d 350","y":1996,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/102/350/","by":{"0":"20"}},{"t":"case","label":"Ransom v. FIA Card Servs., N.A.","cite":"131 S. Ct. 716","y":2011,"id":"2010/09-907","sc":1,"sum":"The Court held that a debtor who does not make a loan or lease payment could not take the car-ownership deduction.","sumSrc":"Oyez","by":{"0":"17"}},{"t":"case","label":"Rodriguez v. United States","cite":"480 U.S. 522","y":1987,"id":"1986/86-5504","sc":1,"sum":"Section 3147 does not divest sentencing judges of their § 3651 authority. Nothing in the language of the two provisions suggests the existence of an \"irreconcilable conflict\" from which an intent to work an implicit partial repeal of § 3651 may be inferred; to the contrary, the provisions fit together quite sensibly. Moreover, the totality of the legislative history of the Act of which §3147 is a part demonstrates …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20"}},{"t":"case","label":"Travelers Cas. & Sur. Co. v. Pacific Gas & Elec. Co.","cite":"549 U.S. 443","y":2007,"id":"2006/05-1429","sc":1,"sum":"Justice Samuel Alito issued the unanimous opinion, which found that the Bankruptcy Code did not expressly waive the contractual obligation to reimburse attorney fees even if incurred in federal litigation.","sumSrc":"Oyez","by":{"0":"19"}},{"t":"case","label":"United States v. Hillsborough Holdings Corp.","cite":"116 F.3d 1391","y":1997,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/116/1391/","op":1,"by":{"0":"19, 26"}},{"t":"case","label":"United States v. Noland","cite":"517 U.S. 534","y":1996,"id":"1995/95-323","sc":1,"op":2,"sum":"Announced by Justice David H. Souter, the Court ruled that giving tax-penalty claims a lower priority than other claims contradicts Congress_ scheme of priorities regarding federal bankruptcy law.","sumSrc":"Oyez","by":{"0":"26, 29"}},{"t":"case","label":"Valen Mfg. Co. v. United States","cite":"90 F.3d 1190","y":1996,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/90/1190/","by":{"0":"25"}},{"t":"law","label":"Pub. L. No. 109-8","url":"https://www.govinfo.gov/link/plaw/109/public/8","by":{"0":"2"}},{"t":"usc","label":"11 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/11/701","by":{"0":"30, 9, 11, 22, 26, 30, 35"}},{"t":"usc","label":"11 U.S.C. § 101","url":"https://www.law.cornell.edu/uscode/text/11/101","subs":["(10)(A)","(10)(B)"],"stext":{"head":"§101. Definitions","paras":[[0,"In this title the following definitions shall apply:"],[1,"(1) The term \"accountant\" means accountant authorized under applicable law to practice public accounting, and includes professional accounting association, corporation, or partnership, if so authorized."],[1,"(2) The term \"affiliate\" means—"],[2,"(A) entity that directly or indirectly owns, controls, or holds with power to vote, 20 percent or more of the outstanding voting securities of the debtor, other than an entity that holds such securities—"],[3,"(i) in a fiduciary or agency capacity without sole discretionary power to vote such securities; or"],[3,"(ii) solely to secure a debt, if such entity has not in fact exercised such power to vote;"],[2,"(B) corporation 20 percent or more of whose outstanding voting securities are directly or indirectly owned, controlled, or held with power to vote, by the debtor, or by an entity that directly or indirectly owns, controls, or holds with power to vote, 20 percent or more of the outstanding voting securities of the debtor, other than an entity that holds such securities—"],[3,"(i) in a fiduciary or agency capacity without sole discretionary power to vote such securities; or"],[3,"(ii) solely to secure a debt, if such entity has not in fact exercised such power to vote;"],[2,"(C) person whose business is operated under a lease or operating agreement by a debtor, or person substantially all of whose property is operated under an operating agreement with the debtor; or"],[2,"(D) entity that operates the business or substantially all of the property of the debtor under a lease or operating agreement."],[1,"(3) The term \"assisted person\" means any person whose debts consist primarily of consumer debts and the value of whose nonexempt property is less than $150,000.1"],[1,"(4) The term \"attorney\" means attorney, professional law association, corporation, or partnership, authorized under applicable law to practice law."],[1,"(4A) The term \"bankruptcy assistance\" means any goods or services sold or otherwise provided to an assisted person with the express or implied purpose of providing information, advice, counsel, document preparation, or filing, or attendance at a creditors' meeting or appearing in a case or proceeding on behalf of another or providing legal representation with respect to a case or proceeding under this title."],[1,"(5) The term \"claim\" means—"],[2,"(A) right to payment, whether or not such right is reduced to judgment, liquidated, unliquidated, fixed, contingent, matured, unmatured, disputed, undisputed, legal, equitable, secured, or unsecured; or"],[2,"(B) right to an equitable remedy for breach of performance if such breach gives rise to a right to payment, whether or not such right to an equitable remedy is reduced to judgment, fixed, contingent, matured, unmatured, disputed, undisputed, secured, or unsecured."],[1,"(6) The term \"commodity broker\" means futures commission merchant, foreign futures commission merchant, clearing organization, leverage transaction merchant, or commodity options dealer, as defined in section 761 of this title, with respect to which there is a customer, as defined in section 761 of this title."],[1,"(7) The term \"community claim\" means claim that arose before the commencement of the case concerning the debtor for which property of the kind specified in section 541(a)(2) of this title is liable, whether or not there is any such property at the time of the commencement of the case."],[1,"(7A) The term \"commercial fishing operation\" means—"],[2,"(A) the catching or harvesting of fish, shrimp, lobsters, urchins, seaweed, shellfish, or other aquatic species or products of such species; or"],[2,"(B) for purposes of section 109 and chapter 12, aquaculture activities consisting of raising for market any species or product described in subparagraph (A)."],[1,"(7B) The term \"commercial fishing vessel\" means a vessel used by a family fisherman to carry out a commercial fishing operation."],[1,"(8) The term \"consumer debt\" means debt incurred by an individual primarily for a personal, family, or household purpose."],[1,"(9) The term \"corporation\"—"],[2,"(A) includes—"],[3,"(i) association having a power or privilege that a private corporation, but not an individual or a partnership, possesses;"],[3,"(ii) partnership association organized under a law that makes only the capital subscribed responsible for the debts of such association;"],[3,"(iii) joint-stock company;"],[3,"(iv) unincorporated company or association; or"],[3,"(v) business trust; but"],[2,"(B) does not include limited partnership."],[1,"(10) The term \"creditor\" means—"],[2,"(A) entity that has a claim against the debtor that arose at the time of or before the order for relief concerning the debtor;"],[2,"(B) entity that has a claim against the estate of a kind specified in section 348(d), 502(f), 502(g), 502(h) or 502(i) of this title; or"],[2,"(C) entity that has a community claim."],[1,"(10A) The term \"current monthly income\"—"],[2,"(A) means the average monthly income from all sources that the debtor receives (or in a joint case the debtor and the debtor's spouse receive) without regard to whether such income is taxable income, derived during the 6-month period ending on—"],[3,"(i) the last day of the calendar month immediately preceding the date of the commencement of the case if the debtor files the schedule of current income required by section 521(a)(1)(B)(ii); or"],[3,"(ii) the date on which current income is determined by the court for purposes of this title if the debtor does not file the schedule of current income required by section 521(a)(1)(B)(ii); and"],[2,"(B)(i) includes any amount paid by any entity other than the debtor (or in a joint case the debtor and the debtor's spouse), on a regular basis for the household expenses of the debtor or the debtor's dependents (and in a joint case the debtor's spouse if not otherwise a dependent); and"],[2,"(ii) excludes—"],[3,"(I) benefits received under the Social Security Act (42 U.S.C. 301 et seq.);"],[3,"(II) payments to victims of war crimes or crimes against humanity on account of their status as victims of such crimes;"],[3,"(III) payments to victims of international terrorism or domestic terrorism, as those terms are defined in section 2331 of title 18, on account of their status as victims of such terrorism; and"],[3,"(IV) any monthly compensation, pension, pay, annuity, or allowance paid under title 10, 37, or 38 in connection with a disability, combat-related injury or disability, or death of a member of the uniformed services, except that any retired pay excluded under this subclause shall include retired pay paid under chapter 61 of title 10 only to the extent that such retired pay exceeds the amount of retired pay to which the debtor would otherwise be entitled if retired under any provision of title 10 other than chapter 61 of that title."],[1,"(11) The term \"custodian\" means—"],[2,"(A) receiver or trustee of any of the property of the debtor, appointed in a case or proceeding not under this title;"],[2,"(B) assignee under a general assignment for the benefit of the debtor's creditors; or"],[2,"(C) trustee, receiver, or agent under applicable law, or under a contract, that is appointed or authorized to take charge of property of the debtor for the purpose of enforcing a lien against such property, or for the purpose of general administration of such property for the benefit of the debtor's creditors."],[1,"(12) The term \"debt\" means liability on a claim."],[1,"(12A) The term \"debt relief agency\" means any person who provides any bankruptcy assistance to an assisted person in return for the payment of money or other valuable consideration, or who is a bankruptcy petition preparer under section 110, but does not include—"],[2,"(A) any person who is an officer, director, employee, or agent of a person who provides such assistance or of the bankruptcy petition preparer;"],[2,"(B) a nonprofit organization that is exempt from taxation under section 501(c)(3) of the Internal Revenue Code of 1986;"],[2,"(C) a creditor of such assisted person, to the extent that the creditor is assisting such assisted person to restructure any debt owed by such assisted person to the creditor;"],[2,"(D) a depository institution (as defined in section 3 of the Federal Deposit Insurance Act) or any Federal credit union or State credit union (as those terms are defined in section 101 of the Federal Credit Union Act), or any affiliate or subsidiary of such depository institution or credit union; or"],[2,"(E) an author, publisher, distributor, or seller of works subject to copyright protection under title 17, when acting in such capacity."],[1,"(13) The term \"debtor\" means person or municipality concerning which a case under this title has been commenced."],[1,"(13A) The term \"debtor's principal residence\"—"],[2,"(A) means a residential structure if used as the principal residence by the debtor, including incidental property, without regard to whether that structure is attached to real property; and"],[2,"(B) includes an individual condominium or cooperative unit, a mobile or manufactured home, or trailer if used as the principal residence by the debtor."],[1,"(14) The term \"disinterested person\" means a person that—"],[2,"(A) is not a creditor, an equity security holder, or an insider;"],[2,"(B) is not and was not, within 2 years before the date of the filing of the petition, a director, officer, or employee of the debtor; and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/101?type=usc&year=mostrecent&link-type=html"},"ar":2,"head":"§101. Definitions","tname":"Bankruptcy","by":{"0":"2, 12, 2, 12, 13"}},{"t":"usc","label":"11 U.S.C. § 301","url":"https://www.law.cornell.edu/uscode/text/11/301","by":{"0":"2"}},{"t":"usc","label":"11 U.S.C. § 346","url":"https://www.law.cornell.edu/uscode/text/11/346","subs":["(1982)","(b)","(b)(1)(1982)","(c)(1)(1982)","(d)(1982)"],"stext":{"head":"§346. Special provisions related to the treatment of State and local taxes","paras":[[0,"(a) Whenever the Internal Revenue Code of 1986 provides that a separate taxable estate or entity is created in a case concerning a debtor under this title, and the income, gain, loss, deductions, and credits of such estate shall be taxed to or claimed by the estate, a separate taxable estate is also created for purposes of any State and local law imposing a tax on or measured by income and such income, gain, loss, deductions, and credits shall be taxed to or claimed by the estate and may not be taxed to or claimed by the debtor. The preceding sentence shall not apply if the case is dismissed. The trustee shall make tax returns of income required under any such State or local law."],[0,"(b) Whenever the Internal Revenue Code of 1986 provides that no separate taxable estate shall be created in a case concerning a debtor under this title, and the income, gain, loss, deductions, and credits of an estate shall be taxed to or claimed by the debtor, such income, gain, loss, deductions, and credits shall be taxed to or claimed by the debtor under a State or local law imposing a tax on or measured by income and may not be taxed to or claimed by the estate. The trustee shall make such tax returns of income of corporations and of partnerships as are required under any State or local law, but with respect to partnerships, shall make such returns only to the extent such returns are also required to be made under such Code. The estate shall be liable for any tax imposed on such corporation or partnership, but not for any tax imposed on partners or members."],[0,"(c) With respect to a partnership or any entity treated as a partnership under a State or local law imposing a tax on or measured by income that is a debtor in a case under this title, any gain or loss resulting from a distribution of property from such partnership, or any distributive share of any income, gain, loss, deduction, or credit of a partner or member that is distributed, or considered distributed, from such partnership, after the commencement of the case, is gain, loss, income, deduction, or credit, as the case may be, of the partner or member, and if such partner or member is a debtor in a case under this title, shall be subject to tax in accordance with subsection (a) or (b)."],[0,"(d) For purposes of any State or local law imposing a tax on or measured by income, the taxable period of a debtor in a case under this title shall terminate only if and to the extent that the taxable period of such debtor terminates under the Internal Revenue Code of 1986."],[0,"(e) The estate in any case described in subsection (a) shall use the same accounting method as the debtor used immediately before the commencement of the case, if such method of accounting complies with applicable nonbankruptcy tax law."],[0,"(f) For purposes of any State or local law imposing a tax on or measured by income, a transfer of property from the debtor to the estate or from the estate to the debtor shall not be treated as a disposition for purposes of any provision assigning tax consequences to a disposition, except to the extent that such transfer is treated as a disposition under the Internal Revenue Code of 1986."],[0,"(g) Whenever a tax is imposed pursuant to a State or local law imposing a tax on or measured by income pursuant to subsection (a) or (b), such tax shall be imposed at rates generally applicable to the same types of entities under such State or local law."],[0,"(h) The trustee shall withhold from any payment of claims for wages, salaries, commissions, dividends, interest, or other payments, or collect, any amount required to be withheld or collected under applicable State or local tax law, and shall pay such withheld or collected amount to the appropriate governmental unit at the time and in the manner required by such tax law, and with the same priority as the claim from which such amount was withheld or collected was paid."],[0,"(i)(1) To the extent that any State or local law imposing a tax on or measured by income provides for the carryover of any tax attribute from one taxable period to a subsequent taxable period, the estate shall succeed to such tax attribute in any case in which such estate is subject to tax under subsection (a)."],[0,"(2) After such a case is closed or dismissed, the debtor shall succeed to any tax attribute to which the estate succeeded under paragraph (1) to the extent consistent with the Internal Revenue Code of 1986."],[0,"(3) The estate may carry back any loss or tax attribute to a taxable period of the debtor that ended before the date of the order for relief under this title to the extent that—"],[1,"(A) applicable State or local tax law provides for a carryback in the case of the debtor; and"],[1,"(B) the same or a similar tax attribute may be carried back by the estate to such a taxable period of the debtor under the Internal Revenue Code of 1986."],[0,"(j)(1) For purposes of any State or local law imposing a tax on or measured by income, income is not realized by the estate, the debtor, or a successor to the debtor by reason of discharge of indebtedness in a case under this title, except to the extent, if any, that such income is subject to tax under the Internal Revenue Code of 1986."],[0,"(2) Whenever the Internal Revenue Code of 1986 provides that the amount excluded from gross income in respect of the discharge of indebtedness in a case under this title shall be applied to reduce the tax attributes of the debtor or the estate, a similar reduction shall be made under any State or local law imposing a tax on or measured by income to the extent such State or local law recognizes such attributes. Such State or local law may also provide for the reduction of other attributes to the extent that the full amount of income from the discharge of indebtedness has not been applied."],[0,"(k)(1) Except as provided in this section and section 505, the time and manner of filing tax returns and the items of income, gain, loss, deduction, and credit of any taxpayer shall be determined under applicable nonbankruptcy law."],[0,"(2) For Federal tax purposes, the provisions of this section are subject to the Internal Revenue Code of 1986 and other applicable Federal nonbankruptcy law."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/346?type=usc&year=mostrecent&link-type=html"},"op":12,"ar":6,"head":"§346. Special provisions related to the treatment of State and local taxes","tname":"Bankruptcy","by":{"0":"10, 36, 36, 36, 37, 35, 35, 35"}},{"t":"usc","label":"11 U.S.C. § 348","url":"https://www.law.cornell.edu/uscode/text/11/348","subs":["(d)"],"by":{"0":"13"}},{"t":"usc","label":"11 U.S.C. § 501","url":"https://www.law.cornell.edu/uscode/text/11/501","subs":["(a)"],"by":{"0":"12"}},{"t":"usc","label":"11 U.S.C. § 502","url":"https://www.law.cornell.edu/uscode/text/11/502","subs":["(b)","(g)","(h)","(i)"],"stext":{"head":"§502. Allowance of claims or interests","paras":[[0,"(a) A claim or interest, proof of which is filed under section 501 of this title, is deemed allowed, unless a party in interest, including a creditor of a general partner in a partnership that is a debtor in a case under chapter 7 of this title, objects."],[0,"(b) Except as provided in subsections (e)(2), (f), (g), (h) and (i) of this section, if such objection to a claim is made, the court, after notice and a hearing, shall determine the amount of such claim in lawful currency of the United States as of the date of the filing of the petition, and shall allow such claim in such amount, except to the extent that—"],[1,"(1) such claim is unenforceable against the debtor and property of the debtor, under any agreement or applicable law for a reason other than because such claim is contingent or unmatured;"],[1,"(2) such claim is for unmatured interest;"],[1,"(3) if such claim is for a tax assessed against property of the estate, such claim exceeds the value of the interest of the estate in such property;"],[1,"(4) if such claim is for services of an insider or attorney of the debtor, such claim exceeds the reasonable value of such services;"],[1,"(5) such claim is for a debt that is unmatured on the date of the filing of the petition and that is excepted from discharge under section 523(a)(5) of this title;"],[1,"(6) if such claim is the claim of a lessor for damages resulting from the termination of a lease of real property, such claim exceeds—"],[2,"(A) the rent reserved by such lease, without acceleration, for the greater of one year, or 15 percent, not to exceed three years, of the remaining term of such lease, following the earlier of—"],[3,"(i) the date of the filing of the petition; and"],[3,"(ii) the date on which such lessor repossessed, or the lessee surrendered, the leased property; plus"],[2,"(B) any unpaid rent due under such lease, without acceleration, on the earlier of such dates;"],[1,"(7) if such claim is the claim of an employee for damages resulting from the termination of an employment contract, such claim exceeds—"],[2,"(A) the compensation provided by such contract, without acceleration, for one year following the earlier of—"],[3,"(i) the date of the filing of the petition; or"],[3,"(ii) the date on which the employer directed the employee to terminate, or such employee terminated, performance under such contract; plus"],[2,"(B) any unpaid compensation due under such contract, without acceleration, on the earlier of such dates;"],[1,"(8) such claim results from a reduction, due to late payment, in the amount of an otherwise applicable credit available to the debtor in connection with an employment tax on wages, salaries, or commissions earned from the debtor; or"],[1,"(9) proof of such claim is not timely filed, except to the extent tardily filed as permitted under paragraph (1), (2), or (3) of section 726(a) or under the Federal Rules of Bankruptcy Procedure, except that—"],[2,"(A) a claim of a governmental unit shall be timely filed if it is filed before 180 days after the date of the order for relief or such later time as the Federal Rules of Bankruptcy Procedure may provide; and"],[2,"(B) in a case under chapter 13, a claim of a governmental unit for a tax with respect to a return filed under section 1308 shall be timely if the claim is filed on or before the date that is 60 days after the date on which such return was filed as required."],[0,"(c) There shall be estimated for purpose of allowance under this section—"],[1,"(1) any contingent or unliquidated claim, the fixing or liquidation of which, as the case may be, would unduly delay the administration of the case; or"],[1,"(2) any right to payment arising from a right to an equitable remedy for breach of performance."],[0,"(d) Notwithstanding subsections (a) and (b) of this section, the court shall disallow any claim of any entity from which property is recoverable under section 542, 543, 550, or 553 of this title or that is a transferee of a transfer avoidable under section 522(f), 522(h), 544, 545, 547, 548, 549, or 724(a) of this title, unless such entity or transferee has paid the amount, or turned over any such property, for which such entity or transferee is liable under section 522(i), 542, 543, 550, or 553 of this title."],[0,"(e)(1) Notwithstanding subsections (a), (b), and (c) of this section and paragraph (2) of this subsection, the court shall disallow any claim for reimbursement or contribution of an entity that is liable with the debtor on or has secured the claim of a creditor, to the extent that—"],[1,"(A) such creditor's claim against the estate is disallowed;"],[1,"(B) such claim for reimbursement or contribution is contingent as of the time of allowance or disallowance of such claim for reimbursement or contribution; or"],[1,"(C) such entity asserts a right of subrogation to the rights of such creditor under section 509 of this title."],[0,"(2) A claim for reimbursement or contribution of such an entity that becomes fixed after the commencement of the case shall be determined, and shall be allowed under subsection (a), (b), or (c) of this section, or disallowed under subsection (d) of this section, the same as if such claim had become fixed before the date of the filing of the petition."],[0,"(f) In an involuntary case, a claim arising in the ordinary course of the debtor's business or financial affairs after the commencement of the case but before the earlier of the appointment of a trustee and the order for relief shall be determined as of the date such claim arises, and shall be allowed under subsection (a), (b), or (c) of this section or disallowed under subsection (d) or (e) of this section, the same as if such claim had arisen before the date of the filing of the petition."],[0,"(g)(1) A claim arising from the rejection, under section 365 of this title or under a plan under chapter 9, 11, 12, or 13 of this title, of an executory contract or unexpired lease of the debtor that has not been assumed shall be determined, and shall be allowed under subsection (a), (b), or (c) of this section or disallowed under subsection (d) or (e) of this section, the same as if such claim had arisen before the date of the filing of the petition."],[0,"(2) A claim for damages calculated in accordance with section 562 shall be allowed under subsection (a), (b), or (c), or disallowed under subsection (d) or (e), as if such claim had arisen before the date of the filing of the petition."],[0,"(h) A claim arising from the recovery of property under section 522, 550, or 553 of this title shall be determined, and shall be allowed under subsection (a), (b), or (c) of this section, or disallowed under subsection (d) or (e) of this section, the same as if such claim had arisen before the date of the filing of the petition."],[0,"(i) A claim that does not arise until after the commencement of the case for a tax entitled to priority under section 507(a)(8) of this title shall be determined, and shall be allowed under subsection (a), (b), or (c) of this section, or disallowed under subsection (d) or (e) of this section, the same as if such claim had arisen before the date of the filing of the petition."],[0,"(j) A claim that has been allowed or disallowed may be reconsidered for cause. A reconsidered claim may be allowed or disallowed according to the equities of the case. Reconsideration of a claim under this subsection does not affect the validity of any payment or transfer from the estate made to a holder of an allowed claim on account of such allowed claim that is not reconsidered, but if a reconsidered claim is allowed and is of the same class as such holder's claim, such holder may not receive any additional payment or transfer from the estate on account of such holder's allowed claim until the holder of such reconsidered and allowed claim receives payment on account of such claim proportionate in value to that already received by such other holder. This subsection does not alter or modify the trustee's right to recover from a creditor any excess payment or transfer made to such creditor."],[0,"(k)(1) The court, on the motion of the debtor and after a hearing, may reduce a claim filed under this section based in whole on an unsecured consumer debt by not more than 20 percent of the claim, if—"],[1,"(A) the claim was filed by a creditor who unreasonably refused to negotiate a reasonable alternative repayment schedule proposed on behalf of the debtor by an approved nonprofit budget and credit counseling agency described in section 111;"],[1,"(B) the offer of the debtor under subparagraph (A)—"],[2,"(i) was made at least 60 days before the date of the filing of the petition; and"],[2,"(ii) provided for payment of at least 60 percent of the amount of the debt over a period not to exceed the repayment period of the loan, or a reasonable extension thereof; and"],[1,"(C) no part of the debt under the alternative repayment schedule is nondischargeable."],[0,"(2) The debtor shall have the burden of proving, by clear and convincing evidence, that—"],[1,"(A) the creditor unreasonably refused to consider the debtor's proposal; and"],[1,"(B) the proposed alternative repayment schedule was made prior to expiration of the 60-day period specified in paragraph (1)(B)(i)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/502?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§502. Allowance of claims or interests","tname":"Bankruptcy","by":{"0":"13, 13, 13, 13, 13"}},{"t":"usc","label":"11 U.S.C. § 503","url":"https://www.law.cornell.edu/uscode/text/11/503","subs":["(a)","(b)","(b)(1)(A)","(b)(1)(A)(i)","(b)(1)(B)","(b)(1)(B)(i)","(b)(1)(B)(ii)","(b)(1)(C)","(b)(2)"],"stext":{"head":"§503. Allowance of administrative expenses","paras":[[0,"(a) An entity may timely file a request for payment of an administrative expense, or may tardily file such request if permitted by the court for cause."],[0,"(b) After notice and a hearing, there shall be allowed administrative expenses, other than claims allowed under section 502(f) of this title, including—"],[1,"(1)(A) the actual, necessary costs and expenses of preserving the estate including—"],[2,"(i) wages, salaries, and commissions for services rendered after the commencement of the case; and"],[2,"(ii) wages and benefits awarded pursuant to a judicial proceeding or a proceeding of the National Labor Relations Board as back pay attributable to any period of time occurring after commencement of the case under this title, as a result of a violation of Federal or State law by the debtor, without regard to the time of the occurrence of unlawful conduct on which such award is based or to whether any services were rendered, if the court determines that payment of wages and benefits by reason of the operation of this clause will not substantially increase the probability of layoff or termination of current employees, or of nonpayment of domestic support obligations, during the case under this title;"],[1,"(B) any tax—"],[2,"(i) incurred by the estate, whether secured or unsecured, including property taxes for which liability is in rem, in personam, or both, except a tax of a kind specified in section 507(a)(8) of this title; or"],[2,"(ii) attributable to an excessive allowance of a tentative carryback adjustment that the estate received, whether the taxable year to which such adjustment relates ended before or after the commencement of the case;"],[1,"(C) any fine, penalty, or reduction in credit relating to a tax of a kind specified in subparagraph (B) of this paragraph; and"],[1,"(D) notwithstanding the requirements of subsection (a), a governmental unit shall not be required to file a request for the payment of an expense described in subparagraph (B) or (C), as a condition of its being an allowed administrative expense;"],[1,"(2) compensation and reimbursement awarded under section 330(a) of this title;"],[1,"(3) the actual, necessary expenses, other than compensation and reimbursement specified in paragraph (4) of this subsection, incurred by—"],[2,"(A) a creditor that files a petition under section 303 of this title;"],[2,"(B) a creditor that recovers, after the court's approval, for the benefit of the estate any property transferred or concealed by the debtor;"],[2,"(C) a creditor in connection with the prosecution of a criminal offense relating to the case or to the business or property of the debtor;"],[2,"(D) a creditor, an indenture trustee, an equity security holder, or a committee representing creditors or equity security holders other than a committee appointed under section 1102 of this title, in making a substantial contribution in a case under chapter 9 or 11 of this title;"],[2,"(E) a custodian superseded under section 543 of this title, and compensation for the services of such custodian; or"],[2,"(F) a member of a committee appointed under section 1102 of this title, if such expenses are incurred in the performance of the duties of such committee;"],[1,"(4) reasonable compensation for professional services rendered by an attorney or an accountant of an entity whose expense is allowable under subparagraph (A), (B), (C), (D), or (E) of paragraph (3) of this subsection, based on the time, the nature, the extent, and the value of such services, and the cost of comparable services other than in a case under this title, and reimbursement for actual, necessary expenses incurred by such attorney or accountant;"],[1,"(5) reasonable compensation for services rendered by an indenture trustee in making a substantial contribution in a case under chapter 9 or 11 of this title, based on the time, the nature, the extent, and the value of such services, and the cost of comparable services other than in a case under this title;"],[1,"(6) the fees and mileage payable under chapter 119 of title 28;"],[1,"(7) with respect to a nonresidential real property lease previously assumed under section 365, and subsequently rejected, a sum equal to all monetary obligations due, excluding those arising from or relating to a failure to operate or a penalty provision, for the period of 2 years following the later of the rejection date or the date of actual turnover of the premises, without reduction or setoff for any reason whatsoever except for sums actually received or to be received from an entity other than the debtor, and the claim for remaining sums due for the balance of the term of the lease shall be a claim under section 502(b)(6);"],[1,"(8) the actual, necessary costs and expenses of closing a health care business incurred by a trustee or by a Federal agency (as defined in section 551(1) of title 5) or a department or agency of a State or political subdivision thereof, including any cost or expense incurred—"],[2,"(A) in disposing of patient records in accordance with section 351; or"],[2,"(B) in connection with transferring patients from the health care business that is in the process of being closed to another health care business; and"],[1,"(9) the value of any goods received by the debtor within 20 days before the date of commencement of a case under this title in which the goods have been sold to the debtor in the ordinary course of such debtor's business."],[0,"(c) Notwithstanding subsection (b), there shall neither be allowed, nor paid—"],[1,"(1) a transfer made to, or an obligation incurred for the benefit of, an insider of the debtor for the purpose of inducing such person to remain with the debtor's business, absent a finding by the court based on evidence in the record that—"],[2,"(A) the transfer or obligation is essential to retention of the person because the individual has a bona fide job offer from another business at the same or greater rate of compensation;"],[2,"(B) the services provided by the person are essential to the survival of the business; and"],[2,"(C) either—"],[3,"(i) the amount of the transfer made to, or obligation incurred for the benefit of, the person is not greater than an amount equal to 10 times the amount of the mean transfer or obligation of a similar kind given to nonmanagement employees for any purpose during the calendar year in which the transfer is made or the obligation is incurred; or"],[3,"(ii) if no such similar transfers were made to, or obligations were incurred for the benefit of, such nonmanagement employees during such calendar year, the amount of the transfer or obligation is not greater than an amount equal to 25 percent of the amount of any similar transfer or obligation made to or incurred for the benefit of such insider for any purpose during the calendar year before the year in which such transfer is made or obligation is incurred;"],[1,"(2) a severance payment to an insider of the debtor, unless—"],[2,"(A) the payment is part of a program that is generally applicable to all full-time employees; and"],[2,"(B) the amount of the payment is not greater than 10 times the amount of the mean severance pay given to nonmanagement employees during the calendar year in which the payment is made; or"],[1,"(3) other transfers or obligations that are outside the ordinary course of business and not justified by the facts and circumstances of the case, including transfers made to, or obligations incurred for the benefit of, officers, managers, or consultants hired after the date of the filing of the petition."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/503?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§503. Allowance of administrative expenses","tname":"Bankruptcy","by":{"0":"30, 12, 3, 6, 15, 22, 29, 34, 14, 15, 3, 27, 4, 5, 8, 22, 3, 5, 22, 22, 29, 14, 15"}},{"t":"usc","label":"11 U.S.C. § 507","url":"https://www.law.cornell.edu/uscode/text/11/507","subs":["(a)","(a)(1)","(a)(2)","(a)(3)","(a)(8)","(a)(8)(A)"],"stext":{"head":"§507. Priorities","paras":[[0,"(a) The following expenses and claims have priority in the following order:"],[1,"(1) First:"],[2,"(A) Allowed unsecured claims for domestic support obligations that, as of the date of the filing of the petition in a case under this title, are owed to or recoverable by a spouse, former spouse, or child of the debtor, or such child's parent, legal guardian, or responsible relative, without regard to whether the claim is filed by such person or is filed by a governmental unit on behalf of such person, on the condition that funds received under this paragraph by a governmental unit under this title after the date of the filing of the petition shall be applied and distributed in accordance with applicable nonbankruptcy law."],[2,"(B) Subject to claims under subparagraph (A), allowed unsecured claims for domestic support obligations that, as of the date of the filing of the petition, are assigned by a spouse, former spouse, child of the debtor, or such child's parent, legal guardian, or responsible relative to a governmental unit (unless such obligation is assigned voluntarily by the spouse, former spouse, child, parent, legal guardian, or responsible relative of the child for the purpose of collecting the debt) or are owed directly to or recoverable by a governmental unit under applicable nonbankruptcy law, on the condition that funds received under this paragraph by a governmental unit under this title after the date of the filing of the petition be applied and distributed in accordance with applicable nonbankruptcy law."],[2,"(C) If a trustee is appointed or elected under section 701, 702, 703, 1104, 1202, or 1302, the administrative expenses of the trustee allowed under paragraphs (1)(A), (2), and (6) of section 503(b) shall be paid before payment of claims under subparagraphs (A) and (B), to the extent that the trustee administers assets that are otherwise available for the payment of such claims."],[1,"(2) Second, administrative expenses allowed under section 503(b) of this title, unsecured claims of any Federal reserve bank related to loans made through programs or facilities authorized under section 13(3) of the Federal Reserve Act (12 U.S.C. 343),1 and any fees and charges assessed against the estate under chapter 123 of title 28."],[1,"(3) Third, unsecured claims allowed under section 502(f) of this title."],[1,"(4) Fourth, allowed unsecured claims, but only to the extent of $10,000 2 for each individual or corporation, as the case may be, earned within 180 days before the date of the filing of the petition or the date of the cessation of the debtor's business, whichever occurs first, for—"],[2,"(A) wages, salaries, or commissions, including vacation, severance, and sick leave pay earned by an individual; or"],[2,"(B) sales commissions earned by an individual or by a corporation with only 1 employee, acting as an independent contractor in the sale of goods or services for the debtor in the ordinary course of the debtor's business if, and only if, during the 12 months preceding that date, at least 75 percent of the amount that the individual or corporation earned by acting as an independent contractor in the sale of goods or services was earned from the debtor."],[1,"(5) Fifth, allowed unsecured claims for contributions to an employee benefit plan—"],[2,"(A) arising from services rendered within 180 days before the date of the filing of the petition or the date of the cessation of the debtor's business, whichever occurs first; but only"],[2,"(B) for each such plan, to the extent of—"],[3,"(i) the number of employees covered by each such plan multiplied by $10,000; 2 less"],[3,"(ii) the aggregate amount paid to such employees under paragraph (4) of this subsection, plus the aggregate amount paid by the estate on behalf of such employees to any other employee benefit plan."],[1,"(6) Sixth, allowed unsecured claims of persons—"],[2,"(A) engaged in the production or raising of grain, as defined in section 557(b) of this title, against a debtor who owns or operates a grain storage facility, as defined in section 557(b) of this title, for grain or the proceeds of grain, or"],[2,"(B) engaged as a United States fisherman against a debtor who has acquired fish or fish produce from a fisherman through a sale or conversion, and who is engaged in operating a fish produce storage or processing facility—"],[1,"but only to the extent of $4,000 2 for each such individual."],[1,"(7) Seventh, allowed unsecured claims of individuals, to the extent of $1,800 2 for each such individual, arising from the deposit, before the commencement of the case, of money in connection with the purchase, lease, or rental of property, or the purchase of services, for the personal, family, or household use of such individuals, that were not delivered or provided."],[1,"(8) Eighth, allowed unsecured claims of governmental units, only to the extent that such claims are for—"],[2,"(A) a tax on or measured by income or gross receipts for a taxable year ending on or before the date of the filing of the petition—"],[3,"(i) for which a return, if required, is last due, including extensions, after three years before the date of the filing of the petition;"],[3,"(ii) assessed within 240 days before the date of the filing of the petition, exclusive of—"],[4,"(I) any time during which an offer in compromise with respect to that tax was pending or in effect during that 240-day period, plus 30 days; and"],[4,"(II) any time during which a stay of proceedings against collections was in effect in a prior case under this title during that 240-day period, plus 90 days; or"],[3,"(iii) other than a tax of a kind specified in section 523(a)(1)(B) or 523(a)(1)(C) of this title, not assessed before, but assessable, under applicable law or by agreement, after, the commencement of the case;"],[2,"(B) a property tax incurred before the commencement of the case and last payable without penalty after one year before the date of the filing of the petition;"],[2,"(C) a tax required to be collected or withheld and for which the debtor is liable in whatever capacity;"],[2,"(D) an employment tax on a wage, salary, or commission of a kind specified in paragraph (4) of this subsection earned from the debtor before the date of the filing of the petition, whether or not actually paid before such date, for which a return is last due, under applicable law or under any extension, after three years before the date of the filing of the petition;"],[2,"(E) an excise tax on—"],[3,"(i) a transaction occurring before the date of the filing of the petition for which a return, if required, is last due, under applicable law or under any extension, after three years before the date of the filing of the petition; or"],[3,"(ii) if a return is not required, a transaction occurring during the three years immediately preceding the date of the filing of the petition;"],[2,"(F) a customs duty arising out of the importation of merchandise—"],[3,"(i) entered for consumption within one year before the date of the filing of the petition;"],[3,"(ii) covered by an entry liquidated or reliquidated within one year before the date of the filing of the petition; or"],[3,"(iii) entered for consumption within four years before the date of the filing of the petition but unliquidated on such date, if the Secretary of the Treasury certifies that failure to liquidate such entry was due to an investigation pending on such date into assessment of antidumping or countervailing duties or fraud, or if information needed for the proper appraisement or classification of such merchandise was not available to the appropriate customs officer before such date; or"],[2,"(G) a penalty related to a claim of a kind specified in this paragraph and in compensation for actual pecuniary loss."],[1,"An otherwise applicable time period specified in this paragraph shall be suspended for any period during which a governmental unit is prohibited under applicable nonbankruptcy law from collecting a tax as a result of a request by the debtor for a hearing and an appeal of any collection action taken or proposed against the debtor, plus 90 days; plus any time during which the stay of proceedings was in effect in a prior case under this title or during which collection was precluded by the existence of 1 or more confirmed plans under this title, plus 90 days."],[1,"(9) Ninth, allowed unsecured claims based upon any commitment by the debtor to a Federal depository institutions regulatory agency (or predecessor to such agency) to maintain the capital of an insured depository institution."],[1,"(10) Tenth, allowed claims for death or personal injury resulting from the operation of a motor vehicle or vessel if such operation was unlawful because the debtor was intoxicated from using alcohol, a drug, or another substance."],[0,"(b) If the trustee, under section 362, 363, or 364 of this title, provides adequate protection of the interest of a holder of a claim secured by a lien on property of the debtor and if, notwithstanding such protection, such creditor has a claim allowable under subsection (a)(2) of this section arising from the stay of action against such property under section 362 of this title, from the use, sale, or lease of such property under section 363 of this title, or from the granting of a lien under section 364(d) of this title, then such creditor's claim under such subsection shall have priority over every other claim allowable under such subsection."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/507?type=usc&year=mostrecent&link-type=html"},"op":36,"ar":2,"head":"§507. Priorities","tname":"Bankruptcy","by":{"0":"passim, 3, 13, 13, passim, 13, 8, 18, 19, 22, 3, 19"}},{"t":"usc","label":"11 U.S.C. § 521","url":"https://www.law.cornell.edu/uscode/text/11/521","subs":["(a)(1)(B)"],"by":{"0":"17, 17"}},{"t":"usc","label":"11 U.S.C. § 704","url":"https://www.law.cornell.edu/uscode/text/11/704","subs":["(a)(8)"],"by":{"0":"26"}},{"t":"usc","label":"11 U.S.C. § 726","url":"https://www.law.cornell.edu/uscode/text/11/726","subs":["(b)"],"by":{"0":"14"}},{"t":"usc","label":"11 U.S.C. § 727","url":"https://www.law.cornell.edu/uscode/text/11/727","subs":["(b)"],"by":{"0":"12"}},{"t":"usc","label":"11 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/11/1101","by":{"0":"passim"}},{"t":"usc","label":"11 U.S.C. § 1106","url":"https://www.law.cornell.edu/uscode/text/11/1106","subs":["(a)(1)"],"by":{"0":"26"}},{"t":"usc","label":"11 U.S.C. § 1123","url":"https://www.law.cornell.edu/uscode/text/11/1123","subs":["(a)(1)"],"by":{"0":"14"}},{"t":"usc","label":"11 U.S.C. § 1129","url":"https://www.law.cornell.edu/uscode/text/11/1129","subs":["(a)(9)(A)"],"by":{"0":"14"}},{"t":"usc","label":"11 U.S.C. § 1141","url":"https://www.law.cornell.edu/uscode/text/11/1141","subs":["(d)(1)(A)"],"by":{"0":"12"}},{"t":"usc","label":"11 U.S.C. § 1201","url":"https://www.law.cornell.edu/uscode/text/11/1201","stext":{"head":"§1201. Stay of action against codebtor","paras":[[0,"(a) Except as provided in subsections (b) and (c) of this section, after the order for relief under this chapter, a creditor may not act, or commence or continue any civil action, to collect all or any part of a consumer debt of the debtor from any individual that is liable on such debt with the debtor, or that secured such debt, unless—"],[1,"(1) such individual became liable on or secured such debt in the ordinary course of such individual's business; or"],[1,"(2) the case is closed, dismissed, or converted to a case under chapter 7 of this title."],[0,"(b) A creditor may present a negotiable instrument, and may give notice of dishonor of such an instrument."],[0,"(c) On request of a party in interest and after notice and a hearing, the court shall grant relief from the stay provided by subsection (a) of this section with respect to a creditor, to the extent that—"],[1,"(1) as between the debtor and the individual protected under subsection (a) of this section, such individual received the consideration for the claim held by such creditor;"],[1,"(2) the plan filed by the debtor proposes not to pay such claim; or"],[1,"(3) such creditor's interest would be irreparably harmed by continuation of such stay."],[0,"(d) Twenty days after the filing of a request under subsection (c)(2) of this section for relief from the stay provided by subsection (a) of this section, such stay is terminated with respect to the party in interest making such request, unless the debtor or any individual that is liable on such debt with the debtor files and serves upon such party in interest a written objection to the taking of the proposed action."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/1201?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1201. Stay of action against codebtor","tname":"Bankruptcy","by":{"0":"passim"}},{"t":"usc","label":"11 U.S.C. § 1203","url":"https://www.law.cornell.edu/uscode/text/11/1203","by":{"0":"26"}},{"t":"usc","label":"11 U.S.C. § 1207","url":"https://www.law.cornell.edu/uscode/text/11/1207","stext":{"head":"§1207. Property of the estate","paras":[[0,"(a) Property of the estate includes, in addition to the property specified in section 541 of this title—"],[1,"(1) all property of the kind specified in such section that the debtor acquires after the commencement of the case but before the case is closed, dismissed, or converted to a case under chapter 7 of this title, whichever occurs first; and"],[1,"(2) earnings from services performed by the debtor after the commencement of the case but before the case is closed, dismissed, or converted to a case under chapter 7 of this title, whichever occurs first."],[0,"(b) Except as provided in section 1204, a confirmed plan, or an order confirming a plan, the debtor shall remain in possession of all property of the estate."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/1207?type=usc&year=mostrecent&link-type=html"},"ar":1,"head":"§1207. Property of the estate","tname":"Bankruptcy","by":{"0":"34"}},{"t":"usc","label":"11 U.S.C. § 1222","url":"https://www.law.cornell.edu/uscode/text/11/1222","subs":["(a)(1)","(a)(2)(2000)","(a)(2)","(a)(2)(A)","(c)"],"stext":{"head":"§1222. Contents of plan","paras":[[0,"(a) The plan shall—"],[1,"(1) provide for the submission of all or such portion of future earnings or other future income of the debtor to the supervision and control of the trustee as is necessary for the execution of the plan;"],[1,"(2) provide for the full payment, in deferred cash payments, of all claims entitled to priority under section 507, unless the holder of a particular claim agrees to a different treatment of that claim;"],[1,"(3) if the plan classifies claims and interests, provide the same treatment for each claim or interest within a particular class unless the holder of a particular claim or interest agrees to less favorable treatment;"],[1,"(4) notwithstanding any other provision of this section, a plan may provide for less than full payment of all amounts owed for a claim entitled to priority under section 507(a)(1)(B) only if the plan provides that all of the debtor's projected disposable income for a 5-year period beginning on the date that the first payment is due under the plan will be applied to make payments under the plan; and"],[1,"(5) subject to section 1232, provide for the treatment of any claim by a governmental unit of a kind described in section 1232(a)."],[0,"(b) Subject to subsections (a) and (c) of this section, the plan may—"],[1,"(1) designate a class or classes of unsecured claims, as provided in section 1122 of this title, but may not discriminate unfairly against any class so designated; however, such plan may treat claims for a consumer debt of the debtor if an individual is liable on such consumer debt with the debtor differently than other unsecured claims;"],[1,"(2) modify the rights of holders of secured claims, or of holders of unsecured claims, or leave unaffected the rights of holders of any class of claims;"],[1,"(3) provide for the curing or waiving of any default;"],[1,"(4) provide for payments on any unsecured claim to be made concurrently with payments on any secured claim or any other unsecured claim;"],[1,"(5) provide for the curing of any default within a reasonable time and maintenance of payments while the case is pending on any unsecured claim or secured claim on which the last payment is due after the date on which the final payment under the plan is due;"],[1,"(6) subject to section 365 of this title, provide for the assumption, rejection, or assignment of any executory contract or unexpired lease of the debtor not previously rejected under such section;"],[1,"(7) provide for the payment of all or part of a claim against the debtor from property of the estate or property of the debtor;"],[1,"(8) provide for the sale of all or any part of the property of the estate or the distribution of all or any part of the property of the estate among those having an interest in such property;"],[1,"(9) provide for payment of allowed secured claims consistent with section 1225(a)(5) of this title, over a period exceeding the period permitted under section 1222(c);"],[1,"(10) provide for the vesting of property of the estate, on confirmation of the plan or at a later time, in the debtor or in any other entity;"],[1,"(11) provide for the payment of interest accruing after the date of the filing of the petition on unsecured claims that are nondischargeable under section 1228(a), except that such interest may be paid only to the extent that the debtor has disposable income available to pay such interest after making provision for full payment of all allowed claims; and"],[1,"(12) include any other appropriate provision not inconsistent with this title."],[0,"(c) Except as provided in subsections (b)(5) and (b)(9), the plan may not provide for payments over a period that is longer than three years unless the court for cause approves a longer period, but the court may not approve a period that is longer than five years."],[0,"(d) Notwithstanding subsection (b)(2) of this section and sections 506(b) and 1225(a)(5) of this title, if it is proposed in a plan to cure a default, the amount necessary to cure the default, shall be determined in accordance with the underlying agreement and applicable nonbankruptcy law."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/1222?type=usc&year=mostrecent&link-type=html"},"op":5,"ar":1,"head":"§1222. Contents of plan","tname":"Bankruptcy","by":{"0":"2, 4, 12, 16, 17, 18, 24, passim, passim, 16"}},{"t":"usc","label":"11 U.S.C. § 1225","url":"https://www.law.cornell.edu/uscode/text/11/1225","subs":["(b)(1)(B)","(b)(2)"],"by":{"0":"12, 17, 17"}},{"t":"usc","label":"11 U.S.C. § 1226","url":"https://www.law.cornell.edu/uscode/text/11/1226","subs":["(b)","(b)(1)"],"by":{"0":"28, passim"}},{"t":"usc","label":"11 U.S.C. § 1227","url":"https://www.law.cornell.edu/uscode/text/11/1227","subs":["(a)","(b)"],"by":{"0":"7, 2, 7, 12, 35"}},{"t":"usc","label":"11 U.S.C. § 1228","url":"https://www.law.cornell.edu/uscode/text/11/1228","subs":["(a)"],"stext":{"head":"§1228. Discharge","paras":[[0,"(a) Subject to subsection (d), as soon as practicable after completion by the debtor of all payments under the plan, and in the case of a debtor who is required by a judicial or administrative order, or by statute, to pay a domestic support obligation, after such debtor certifies that all amounts payable under such order or such statute that are due on or before the date of the certification (including amounts due before the petition was filed, but only to the extent provided for by the plan) have been paid, other than payments to holders of allowed claims provided for under section 1222(b)(5) or 1222(b)(9) of this title, unless the court approves a written waiver of discharge executed by the debtor after the order for relief under this chapter, the court shall grant the debtor a discharge of all debts provided for by the plan, allowed under section 503 of this title, or disallowed under section 502 of this title, except any debt—"],[1,"(1) provided for under section 1222(b)(5) or 1222(b)(9) of this title; or"],[1,"(2) of a kind specified in section 523(a) of this title, except as provided in section 1232(c)."],[0,"(b) Subject to subsection (d), at any time after the confirmation of the plan and after notice and a hearing, the court may grant a discharge to a debtor that has not completed payments under the plan only if—"],[1,"(1) the debtor's failure to complete such payments is due to circumstances for which the debtor should not justly be held accountable;"],[1,"(2) the value, as of the effective date of the plan, of property actually distributed under the plan on account of each allowed unsecured claim is not less than the amount that would have been paid on such claim if the estate of the debtor had been liquidated under chapter 7 of this title on such date; and"],[1,"(3) modification of the plan under section 1229 of this title is not practicable."],[0,"(c) A discharge granted under subsection (b) of this section discharges the debtor from all unsecured debts provided for by the plan or disallowed under section 502 of this title, except any debt—"],[1,"(1) provided for under section 1222(b)(5) or 1222(b)(9) of this title; or"],[1,"(2) of a kind specified in section 523(a) of this title, except as provided in section 1232(c)."],[0,"(d) On request of a party in interest before one year after a discharge under this section is granted, and after notice and a hearing, the court may revoke such discharge only if—"],[1,"(1) such discharge was obtained by the debtor through fraud; and"],[1,"(2) the requesting party did not know of such fraud until after such discharge was granted."],[0,"(e) After the debtor is granted a discharge, the court shall terminate the services of any trustee serving in the case."],[0,"(f) The court may not grant a discharge under this chapter unless the court after notice and a hearing held not more than 10 days before the date of the entry of the order granting the discharge finds that there is no reasonable cause to believe that—"],[1,"(1) section 522(q)(1) may be applicable to the debtor; and"],[1,"(2) there is pending any proceeding in which the debtor may be found guilty of a felony of the kind described in section 522(q)(1)(A) or liable for a debt of the kind described in section 522(q)(1)(B)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/1228?type=usc&year=mostrecent&link-type=html"},"ar":1,"head":"§1228. Discharge","tname":"Bankruptcy","by":{"0":"2, 12"}},{"t":"usc","label":"11 U.S.C. § 1301","url":"https://www.law.cornell.edu/uscode/text/11/1301","stext":{"head":"§1301. Stay of action against codebtor","paras":[[0,"(a) Except as provided in subsections (b) and (c) of this section, after the order for relief under this chapter, a creditor may not act, or commence or continue any civil action, to collect all or any part of a consumer debt of the debtor from any individual that is liable on such debt with the debtor, or that secured such debt, unless—"],[1,"(1) such individual became liable on or secured such debt in the ordinary course of such individual's business; or"],[1,"(2) the case is closed, dismissed, or converted to a case under chapter 7 or 11 of this title."],[0,"(b) A creditor may present a negotiable instrument, and may give notice of dishonor of such an instrument."],[0,"(c) On request of a party in interest and after notice and a hearing, the court shall grant relief from the stay provided by subsection (a) of this section with respect to a creditor, to the extent that—"],[1,"(1) as between the debtor and the individual protected under subsection (a) of this section, such individual received the consideration for the claim held by such creditor;"],[1,"(2) the plan filed by the debtor proposes not to pay such claim; or"],[1,"(3) such creditor's interest would be irreparably harmed by continuation of such stay."],[0,"(d) Twenty days after the filing of a request under subsection (c)(2) of this section for relief from the stay provided by subsection (a) of this section, such stay is terminated with respect to the party in interest making such request, unless the debtor or any individual that is liable on such debt with the debtor files and serves upon such party in interest a written objection to the taking of the proposed action."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/1301?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1301. Stay of action against codebtor","tname":"Bankruptcy","by":{"0":"passim"}},{"t":"usc","label":"11 U.S.C. § 1305","url":"https://www.law.cornell.edu/uscode/text/11/1305","subs":["(a)(1)","(b)"],"stext":{"head":"§1305. Filing and allowance of postpetition claims","paras":[[0,"(a) A proof of claim may be filed by any entity that holds a claim against the debtor—"],[1,"(1) for taxes that become payable to a governmental unit while the case is pending; or"],[1,"(2) that is a consumer debt, that arises after the date of the order for relief under this chapter, and that is for property or services necessary for the debtor's performance under the plan."],[0,"(b) Except as provided in subsection (c) of this section, a claim filed under subsection (a) of this section shall be allowed or disallowed under section 502 of this title, but shall be determined as of the date such claim arises, and shall be allowed under section 502(a), 502(b), or 502(c) of this title, or disallowed under section 502(d) or 502(e) of this title, the same as if such claim had arisen before the date of the filing of the petition."],[0,"(c) A claim filed under subsection (a)(2) of this section shall be disallowed if the holder of such claim knew or should have known that prior approval by the trustee of the debtor's incurring the obligation was practicable and was not obtained."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/1305?type=usc&year=mostrecent&link-type=html"},"op":10,"ar":3,"head":"§1305. Filing and allowance of postpetition claims","tname":"Bankruptcy","by":{"0":"8, 10, 21, 38, 39, 21, 39, 39, 21"}},{"t":"usc","label":"11 U.S.C. § 1322","url":"https://www.law.cornell.edu/uscode/text/11/1322","subs":["(a)(2)"],"by":{"0":"21"}},{"t":"usc","label":"11 U.S.C. § 1325","url":"https://www.law.cornell.edu/uscode/text/11/1325","subs":["(b)(1)(B)","(b)(2)"],"by":{"0":"17, 17"}},{"t":"usc","label":"11 U.S.C. § 1326","url":"https://www.law.cornell.edu/uscode/text/11/1326","subs":["(b)","(b)(1)"],"by":{"0":"38, 14, 38, 39"}},{"t":"law","label":"Pub. L. No. 99-554","url":"https://www.govinfo.gov/link/statute/110/3105","by":{"0":"11"}},{"t":"law","label":"Pub. L. No. 95-598","url":"https://www.govinfo.gov/link/statute/92/2549","by":{"0":"30"}},{"t":"law","label":"Pub. L. No. 96-589","url":"https://www.govinfo.gov/link/statute/94/3397","by":{"0":"32"}},{"t":"usc","label":"26 U.S.C. § 1","url":"https://www.law.cornell.edu/uscode/text/26/1","by":{"0":"28"}},{"t":"usc","label":"26 U.S.C. § 1398","url":"https://www.law.cornell.edu/uscode/text/26/1398","subs":["(a)"],"stext":{"head":"§1398. Rules relating to individuals' title 11 cases","paras":[[0,"(a) Cases to which section applies"],[0,"Except as provided in subsection (b), this section shall apply to any case under chapter 7 (relating to liquidations) or chapter 11 (relating to reorganizations) of title 11 of the United States Code in which the debtor is an individual."],[0,"(b) Exceptions where case is dismissed, etc."],[0,"(1) Section does not apply where case is dismissed"],[1,"This section shall not apply if the case under chapter 7 or 11 of title 11 of the United States Code is dismissed."],[0,"(2) Section does not apply at partnership level"],[1,"For purposes of subsection (a), a partnership shall not be treated as an individual, but the interest in a partnership of a debtor who is an individual shall be taken into account under this section in the same manner as any other interest of the debtor."],[0,"(c) Computation and payment of tax; basic standard deduction"],[0,"(1) Computation and payment of tax"],[1,"Except as otherwise provided in this section, the taxable income of the estate shall be computed in the same manner as for an individual. The tax shall be computed on such taxable income and shall be paid by the trustee."],[0,"(2) Tax rates"],[1,"The tax on the taxable income of the estate shall be determined under subsection (d) of section 1."],[0,"(3) Basic standard deduction"],[1,"In the case of an estate which does not itemize deductions, the basic standard deduction for the estate for the taxable year shall be the same as for a married individual filing a separate return for such year."],[0,"(d) Taxable year of debtors"],[0,"(1) General rule"],[1,"Except as provided in paragraph (2), the taxable year of the debtor shall be determined without regard to the case under title 11 of the United States Code to which this section applies."],[0,"(2) Election to terminate debtor's year when case commences"],[0,"(A) In general"],[2,"Notwithstanding section 442, the debtor may (without the approval of the Secretary) elect to treat the debtor's taxable year which includes the commencement date as 2 taxable years—"],[3,"(i) the first of which ends on the day before the commencement date, and"],[3,"(ii) the second of which begins on the commencement date."],[0,"(B) Spouse may join in election"],[2,"In the case of a married individual (within the meaning of section 7703), the spouse may elect to have the debtor's election under subparagraph (A) also apply to the spouse, but only if the debtor and the spouse file a joint return for the taxable year referred to in subparagraph (A)(i)."],[0,"(C) No election where debtor has no assets"],[2,"No election may be made under subparagraph (A) by a debtor who has no assets other than property which the debtor may treat as exempt property under section 522 of title 11 of the United States Code."],[0,"(D) Time for making election"],[2,"An election under subparagraph (A) or (B) may be made only on or before the due date for filing the return for the taxable year referred to in subparagraph (A)(i). Any such election, once made, shall be irrevocable."],[0,"(E) Returns"],[2,"A return shall be made for each of the taxable years specified in subparagraph (A)."],[0,"(F) Annualization"],[2,"For purposes of subsections (b), (c), and (d) of section 443, a return filed for either of the taxable years referred to in subparagraph (A) shall be treated as a return made under paragraph (1) of subsection (a) of section 443."],[0,"(3) Commencement date defined"],[1,"For purposes of this subsection, the term \"commencement date\" means the day on which the case under title 11 of the United States Code to which this section applies commences."],[0,"(e) Treatment of income, deductions, and credits"],[0,"(1) Estate's share of debtor's income"],[1,"The gross income of the estate for each taxable year shall include the gross income of the debtor to which the estate is entitled under title 11 of the United States Code. The preceding sentence shall not apply to any amount received or accrued by the debtor before the commencement date (as defined in subsection (d)(3))."],[0,"(2) Debtor's share of debtor's income"],[1,"The gross income of the debtor for any taxable year shall not include any item to the extent that such item is included in the gross income of the estate by reason of paragraph (1)."],[0,"(3) Rule for making determinations with respect to deductions, credits, and employment taxes"],[1,"Except as otherwise provided in this section, the determination of whether or not any amount paid or incurred by the estate—"],[2,"(A) is allowable as a deduction or credit under this chapter, or"],[2,"(B) is wages for purposes of subtitle C,"],[1,"shall be made as if the amount were paid or incurred by the debtor and as if the debtor were still engaged in the trades and businesses, and in the activities, the debtor was engaged in before the commencement of the case."],[0,"(f) Treatment of transfers between debtor and estate"],[0,"(1) Transfer to estate not treated as disposition"],[1,"A transfer (other than by sale or exchange) of an asset from the debtor to the estate shall not be treated as a disposition for purposes of any provision of this title assigning tax consequences to a disposition, and the estate shall be treated as the debtor would be treated with respect to such asset."],[0,"(2) Transfer from estate to debtor not treated as disposition"],[1,"In the case of a termination of the estate, a transfer (other than by sale or exchange) of an asset from the estate to the debtor shall not be treated as a disposition for purposes of any provision of this title assigning tax consequences to a disposition, and the debtor shall be treated as the estate would be treated with respect to such asset."],[0,"(g) Estate succeeds to tax attributes of debtor"],[0,"The estate shall succeed to and take into account the following items (determined as of the first day of the debtor's taxable year in which the case commences) of the debtor—"],[0,"(1) Net operating loss carryovers"],[1,"The net operating loss carryovers determined under section 172."],[0,"(2) Charitable contributions carryovers"],[1,"The carryover of excess charitable contributions determined under section 170(d)(1)."],[0,"(3) Recovery of tax benefit items"],[1,"Any amount to which section 111 (relating to recovery of tax benefit items) applies."],[0,"(4) Credit carryovers, etc."],[1,"The carryovers of any credit, and all other items which, but for the commencement of the case, would be required to be taken into account by the debtor with respect to any credit."],[0,"(5) Capital loss carryovers"],[1,"The capital loss carryover determined under section 1212."],[0,"(6) Basis, holding period, and character of assets"],[1,"In the case of any asset acquired (other than by sale or exchange) by the estate from the debtor, the basis, holding period, and character it had in the hands of the debtor."],[0,"(7) Method of accounting"],[1,"The method of accounting used by the debtor."],[0,"(8) Other attributes"],[1,"Other tax attributes of the debtor, to the extent provided in regulations prescribed by the Secretary as necessary or appropriate to carry out the purposes of this section."],[0,"(h) Administration, liquidation, and reorganization expenses; carryovers and carrybacks of certain excess expenses"],[0,"(1) Administration, liquidation, and reorganization expenses"],[1,"Any administrative expense allowed under section 503 of title 11 of the United States Code, and any fee or charge assessed against the estate under chapter 123 of title 28 of the United States Code, to the extent not disallowed under any other provision of this title, shall be allowed as a deduction."],[0,"(2) Carryback and carryover of excess administrative costs, etc., to estate taxable years"],[0,"(A) Deduction allowed"],[2,"There shall be allowed as a deduction for the taxable year an amount equal to the aggregate of (i) the administrative expense carryovers to such year, plus (ii) the administrative expense carrybacks to such year."],[0,"(B) Administrative expense loss, etc."],[2,"If a net operating loss would be created or increased for any estate taxable year if section 172(c) were applied without the modification contained in paragraph (4) of section 172(d), then the amount of the net operating loss so created (or the amount of the increase in the net operating loss) shall be an administrative expense loss for such taxable year which shall be an administrative expense carryback to each of the 3 preceding taxable years and an administrative expense carryover to each of the 7 succeeding taxable years."],[0,"(C) Determination of amount carried to each taxable year"],[2,"The portion of any administrative expense loss which may be carried to any other taxable year shall be determined under section 172(b)(2), except that for each taxable year the computation under section 172(b)(2) with respect to the net operating loss shall be made before the computation under this paragraph."],[0,"(D) Administrative expense deductions allowed only to estate"],[2,"The deductions allowable under this chapter solely by reason of paragraph (1), and the deduction provided by subparagraph (A) of this paragraph, shall be allowable only to the estate."],[0,"(i) Debtor succeeds to tax attributes of estate"],[0,"In the case of a termination of an estate, the debtor shall succeed to and take into account the items referred to in paragraphs (1), (2), (3), (4), (5), and (6) of subsection (g) in a manner similar to that provided in such paragraphs (but taking into account that the transfer is from the estate to the debtor instead of from the debtor to the estate). In addition, the debtor shall succeed to and take into account the other tax attributes of the estate, to the extent provided in regulations prescribed by the Secretary as necessary or appropriate to carry out the purposes of this section."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/1398?type=usc&year=mostrecent&link-type=html"},"op":12,"ar":2,"head":"§1398. Rules relating to individuals' title 11 cases","tname":"Internal Revenue Code","by":{"0":"passim, 4"}},{"t":"usc","label":"26 U.S.C. § 1399","url":"https://www.law.cornell.edu/uscode/text/26/1399","stext":{"head":"§1399. No separate taxable entities for partnerships, corporations, etc.","paras":[[0,"Except in any case to which section 1398 applies, no separate taxable entity shall result from the commencement of a case under title 11 of the United States Code."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/1399?type=usc&year=mostrecent&link-type=html"},"op":2,"ar":3,"head":"§1399. No separate taxable entities for partnerships, corporations, etc.","tname":"Internal Revenue Code","by":{"0":"passim"}},{"t":"usc","label":"26 U.S.C. § 3101","url":"https://www.law.cornell.edu/uscode/text/26/3101","by":{"0":"28"}},{"t":"usc","label":"26 U.S.C. § 3102","url":"https://www.law.cornell.edu/uscode/text/26/3102","subs":["(a)"],"by":{"0":"28"}},{"t":"usc","label":"26 U.S.C. § 3402","url":"https://www.law.cornell.edu/uscode/text/26/3402","subs":["(a)"],"by":{"0":"28"}},{"t":"usc","label":"26 U.S.C. § 6012","url":"https://www.law.cornell.edu/uscode/text/26/6012","subs":["(b)(3)"],"stext":{"head":"§6012. Persons required to make returns of income","paras":[[0,"(a) General rule"],[0,"Returns with respect to income taxes under subtitle A shall be made by the following:"],[1,"(1)(A) Every individual having for the taxable year gross income which equals or exceeds the exemption amount, except that a return shall not be required of an individual—"],[2,"(i) who is not married (determined by applying section 7703), is not a surviving spouse (as defined in section 2(a)), is not a head of a household (as defined in section 2(b)), and for the taxable year has gross income of less than the sum of the exemption amount plus the basic standard deduction applicable to such an individual,"],[2,"(ii) who is a head of a household (as so defined) and for the taxable year has gross income of less than the sum of the exemption amount plus the basic standard deduction applicable to such an individual,"],[2,"(iii) who is a surviving spouse (as so defined) and for the taxable year has gross income of less than the sum of the exemption amount plus the basic standard deduction applicable to such an individual, or"],[2,"(iv) who is entitled to make a joint return and whose gross income, when combined with the gross income of his spouse, is, for the taxable year, less than the sum of twice the exemption amount plus the basic standard deduction applicable to a joint return, but only if such individual and his spouse, at the close of the taxable year, had the same household as their home."],[1,"Clause (iv) shall not apply if for the taxable year such spouse makes a separate return or any other taxpayer is entitled to an exemption for such spouse under section 151(c)."],[1,"(B) The amount specified in clause (i), (ii), or (iii) of subparagraph (A) shall be increased by the amount of 1 additional standard deduction (within the meaning of section 63(c)(3)) in the case of an individual entitled to such deduction by reason of section 63(f)(1)(A) (relating to individuals age 65 or more), and the amount specified in clause (iv) of subparagraph (A) shall be increased by the amount of the additional standard deduction for each additional standard deduction to which the individual or his spouse is entitled by reason of section 63(f)(1)."],[1,"(C) The exception under subparagraph (A) shall not apply to any individual—"],[2,"(i) who is described in section 63(c)(5) and who has—"],[3,"(I) income (other than earned income) in excess of the sum of the amount in effect under section 63(c)(5)(A) plus the additional standard deduction (if any) to which the individual is entitled, or"],[3,"(II) total gross income in excess of the standard deduction, or"],[2,"(ii) for whom the standard deduction is zero under section 63(c)(6)."],[1,"(D) For purposes of this subsection—"],[2,"(i) The terms \"standard deduction\", \"basic standard deduction\" and \"additional standard deduction\" have the respective meanings given such terms by section 63(c)."],[2,"(ii) The term \"exemption amount\" has the meaning given such term by section 151(d). In the case of an individual described in section 151(d)(2), the exemption amount shall be zero."],[1,"(2) Every corporation subject to taxation under subtitle A;"],[1,"(3) Every estate the gross income of which for the taxable year is $600 or more;"],[1,"(4) Every trust having for the taxable year any taxable income, or having gross income of $600 or over, regardless of the amount of taxable income;"],[1,"(5) Every estate or trust of which any beneficiary is a nonresident alien;"],[1,"(6) Every political organization (within the meaning of section 527(e)(1)), and every fund treated under section 527(g) as if it constituted a political organization, which has political organization taxable income (within the meaning of section 527(c)(1)) for the taxable year;"],[1,"(7) Every homeowners association (within the meaning of section 528(c)(1)) which has homeowners association taxable income (within the meaning of section 528(d)) for the taxable year; and"],[1,"(8) Every estate of an individual under chapter 7 or 11 of title 11 of the United States Code (relating to bankruptcy) the gross income of which for the taxable year is not less than the sum of the exemption amount plus the basic standard deduction under section 63(c)(2)(C);"],[0,"except that subject to such conditions, limitations, and exceptions and under such regulations as may be prescribed by the Secretary, nonresident alien individuals subject to the tax imposed by section 871 and foreign corporations subject to the tax imposed by section 881 may be exempted from the requirement of making returns under this section."],[0,"(b) Returns made by fiduciaries and receivers"],[0,"(1) Returns of decedents"],[1,"If an individual is deceased, the return of such individual required under subsection (a) shall be made by his executor, administrator, or other person charged with the property of such decedent."],[0,"(2) Persons under a disability"],[1,"If an individual is unable to make a return required under subsection (a), the return of such individual shall be made by a duly authorized agent, his committee, guardian, fiduciary or other person charged with the care of the person or property of such individual. The preceding sentence shall not apply in the case of a receiver appointed by authority of law in possession of only a part of the property of an individual."],[0,"(3) Receivers, trustees and assignees for corporations"],[1,"In a case where a receiver, trustee in a case under title 11 of the United States Code, or assignee, by order of a court of competent jurisdiction, by operation of law or otherwise, has possession of or holds title to all or substantially all the property or business of a corporation, whether or not such property or business is being operated, such receiver, trustee, or assignee shall make the return of income for such corporation in the same manner and form as corporations are required to make such returns."],[0,"(4) Returns of estates and trusts"],[1,"Returns of an estate, a trust, or an estate of an individual under chapter 7 or 11 of title 11 of the United States Code shall be made by the fiduciary thereof."],[0,"(5) Joint fiduciaries"],[1,"Under such regulations as the Secretary may prescribe, a return made by one of two or more joint fiduciaries shall be sufficient compliance with the requirements of this section. A return made pursuant to this paragraph shall contain a statement that the fiduciary has sufficient knowledge of the affairs of the person for whom the return is made to enable him to make the return, and that the return is, to the best of his knowledge and belief, true and correct."],[0,"(6) IRA share of partnership income"],[1,"In the case of a trust which is exempt from taxation under section 408(e), for purposes of this section, the trust's distributive share of items of gross income and gain of any partnership to which subchapter C or D of chapter 63 applies shall be treated as equal to the trust's distributive share of the taxable income of such partnership."],[0,"(c) Certain income earned abroad or from sale of residence"],[0,"For purposes of this section, gross income shall be computed without regard to the exclusion provided for in section 121 (relating to gain from sale of principal residence) and without regard to the exclusion provided for in section 911 (relating to citizens or residents of the United States living abroad)."],[0,"(d) Tax-exempt interest required to be shown on return"],[0,"Every person required to file a return under this section for the taxable year shall include on such return the amount of interest received or accrued during the taxable year which is exempt from the tax imposed by chapter 1."],[0,"(e) Consolidated returns"],[2,"For provisions relating to consolidated returns by affiliated corporations, see chapter 6."],[0,"(f) Special rule for taxable years 2018 through 2025"],[0,"In the case of a taxable year beginning after December 31, 2017, and before January 1, 2026, subsection (a)(1) shall not apply, and every individual who has gross income for the taxable year shall be required to make returns with respect to income taxes under subtitle A, except that a return shall not be required of—"],[1,"(1) an individual who is not married (determined by applying section 7703) and who has gross income for the taxable year which does not exceed the standard deduction applicable to such individual for such taxable year under section 63, or"],[1,"(2) an individual entitled to make a joint return if—"],[2,"(A) the gross income of such individual, when combined with the gross income of such individual's spouse, for the taxable year does not exceed the standard deduction which would be applicable to the taxpayer for such taxable year under section 63 if such individual and such individual's spouse made a joint return,"],[2,"(B) such individual and such individual's spouse have the same household as their home at the close of the taxable year,"],[2,"(C) such individual's spouse does not make a separate return, and"],[2,"(D) neither such individual nor such individual's spouse is an individual described in section 63(c)(5) who has income (other than earned income) in excess of the amount in effect under section 63(c)(5)(A)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/6012?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§6012. Persons required to make returns of income","tname":"Internal Revenue Code","by":{"0":"9, 26"}},{"t":"usc","label":"26 U.S.C. § 6110","url":"https://www.law.cornell.edu/uscode/text/26/6110","subs":["(b)(1)(A)","(i)(1)","(k)(3)"],"by":{"0":"27, 27, 27"}},{"t":"usc","label":"26 U.S.C. § 6151","url":"https://www.law.cornell.edu/uscode/text/26/6151","subs":["(a)"],"by":{"0":"26"}},{"t":"usc","label":"26 U.S.C. § 6651","url":"https://www.law.cornell.edu/uscode/text/26/6651","by":{"0":"33"}},{"t":"usc","label":"26 U.S.C. § 6654","url":"https://www.law.cornell.edu/uscode/text/26/6654","by":{"0":"33"}},{"t":"usc","label":"26 U.S.C. § 6655","url":"https://www.law.cornell.edu/uscode/text/26/6655","by":{"0":"33"}},{"t":"usc","label":"26 U.S.C. § 6658","url":"https://www.law.cornell.edu/uscode/text/26/6658","subs":["(a)(1)"],"by":{"0":"29, 33, 33"}},{"t":"usc","label":"26 U.S.C. § 7501","url":"https://www.law.cornell.edu/uscode/text/26/7501","subs":["(a)"],"by":{"0":"28"}}]};